const fetchReturnQuantity = async () => {
  const tableSR = this.getValue("table_sr") || [];

  const resGDLineData = await Promise.all(
    tableSR.map((item) =>
      db.collection("goods_delivery_fwii8mvb_sub").doc(item.gd_line_id).get(),
    ),
  );

  const gdLineItemData = resGDLineData.map((response) => response.data[0]);

  const updatedTableSR = tableSR.map((item, index) => {
    const gdLine = gdLineItemData[index];
    const totalReturnedQty = gdLine ? gdLine.return_qty || 0 : 0;
    const deliveredQty = gdLine ? gdLine.gd_qty || 0 : 0;
    const maxReturnableQty = deliveredQty - totalReturnedQty;
    return {
      ...item,
      to_returned_qty: maxReturnableQty,
    };
  });

  this.setData({ table_sr: updatedTableSR });
};

