(async () => {
  try {
    const status = await this.getValue("sr_status");

    const pageStatus = this.isAdd
      ? "Add"
      : this.isEdit
        ? "Edit"
        : this.isView
          ? "View"
          : this.isCopy
            ? "Clone"
            : (() => {
                this.$message.error("Invalid page status");
              })();

    let organizationId = this.getVarGlobal("deptParentId");
    if (organizationId === "0") {
      organizationId = this.getVarSystem("deptIds").split(",")[0];
    }

    this.setData({ page_status: pageStatus });

    switch (pageStatus) {
      case "Add":
        this.display(["draft_status"]);
        await setPlant(organizationId);
        await checkAccIntegrationType(organizationId);
        this.setData({
          sr_return_date: new Date().toISOString().split("T")[0],
        });
        break;

      case "Edit":
        this.setData({ previous_status: status });
        await disabledField(status);
        await showStatusHTML(status);
        await checkAccIntegrationType(organizationId);
        await displayPlantAddress();
        await displayDeliveryMethod();
        await fetchReturnQuantity();

        break;

      case "View":
        this.hide([
          "link_billing_address",
          "link_shipping_address",
          "button_save_as_draft",
          "button_save_as_issue",
        ]);

        await showStatusHTML(status);
        await displayPlantAddress();
        await displayDeliveryMethod();

        break;
    }
  } catch (error) {
    this.$message.error(error);
  }
})();

