        .map(so => so?.so_no)
        .filter(Boolean)
        .join(', ');

    this.setData({'so_no_display': displayText});

    let tableSR = [];

    // Create an array to hold all our promises
    const promises = [];

    // Process each so
    for (const so of soData) {
        const soLineItemData = so.table_so || [];
        console.log('soLineItemData for so:', so.so_no, soLineItemData);

        // Process each line item
        if (soLineItemData.length > 0) {
            // Create a promise for each line item and add to our promises array
            soLineItemData.forEach((soItem, index) => {
                promises.push((async () => {
                    console.log("Processing so item:", soItem);

                    const resItem = await db.collection("Item").where({ id: soItem.item_name }).get();
                    const itemData = resItem?.data[0];

                    const srItemData = {
                        material_id: soItem.item_name,
                        material_name: soItem.item_id,
                        material_desc: soItem.so_desc || "",

                        more_desc: soItem.more_desc || "",
                        line_remark_1: soItem.line_remark_1 || "",
                        line_remark_2: soItem.line_remark_2 || "",

                        line_so_no: so.so_no,
                        so_quantity: parseFloat(soItem.so_quantity || 0),
                        good_delivery_qty: parseFloat(soItem.delivered_qty || 0),
                        to_returned_qty: parseFloat(soItem.so_quantity || 0) - parseFloat(soItem.returned_quantity || 0),
                        quantity_uom: soItem.so_item_uom,
                        unit_price: soItem.so_item_price,
                        total_price: soItem.so_amount,
                        returned_quantity: soItem.return_qty || 0,
                    };

                    tableSR.push(srItemData);
                    console.log('srItemData', srItemData);
                })());
            });
        }
    }

    // Wait for all item processing to complete
    await Promise.all(promises);

    console.log('tableSR after all processing:', tableSR);

    // Set the data after processing all sos and all their items
    if (tableSR.length > 0) {
        await this.setData({'table_sr': tableSR});
    }
}

